  /** The request does not match the route's schema */
  "request.invalid": {
    /** The field of the request body that fails the route's schema, as a dotted path. */
    field: string;
  };
  /** The request exceeds a size limit */
  "request.too_large": {
    /** The bound the request passes. */
    limit: number;
    /** The size the request, or the file in it, reached. */
    size: number;
  };
  /** No such route */
  "request.not_found": Record<string, never>;
  /** The route does not accept this HTTP method */
  "request.method_not_allowed": Record<string, never>;
  /** The request uses a form this runtime does not accept */
